"use strict";

const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const state = {
  tab: "practice",
  recorder: null,
  chunks: [],
  recording: false,
  startedAt: 0,
  timer: null,
  audioUrl: null,
  result: null,
  selected: null,
  topics: null,  // connected-speech corpus, loaded when the tab is first opened
  cs: null,      // the chosen connected-speech sentence: {topic, index, sentence}
};

/* ---------- American voice (Kokoro, generated by the server) ---------- */
let voice = null;
function stopAudio() {
  if (voice) { voice.pause(); voice = null; }
  if (currentClip) { try { currentClip.stop(); } catch { /* already ended */ } currentClip = null; }
  $("playback").pause();
}
function speak(text, btn = null) {
  text = text.trim();
  if (text) speakUrl(`/api/speak?text=${encodeURIComponent(text)}`, btn);
}
function speakUrl(url, btn = null) {
  stopAudio();
  const audio = new Audio(url);
  voice = audio;
  if (btn) btn.classList.add("loading");
  const done = () => btn && btn.classList.remove("loading");
  audio.addEventListener("playing", done, { once: true });
  audio.addEventListener("error", () => { done(); showError("The voice isn't available yet. Try again in a moment."); }, { once: true });
  audio.play().catch(done);
}

const soundTile = (say, example) =>
  say ? `<span class="e">${esc(say)}</span>${example ? `<span class="ex">as in ${esc(example)}</span>` : ""}` : `<span class="e">+</span>`;

/* ---------- Tabs ---------- */
document.querySelectorAll(".tab").forEach((btn) =>
  btn.addEventListener("click", () => setTab(btn.dataset.tab))
);
function setTab(tab) {
  state.tab = tab;
  document.querySelectorAll(".tab").forEach((b) => b.classList.toggle("active", b.dataset.tab === tab));
  $("record-panel").hidden = tab === "lookup" || (tab === "connected" && !state.cs);
  $("lookup-panel").hidden = tab !== "lookup";
  $("connected-panel").hidden = tab !== "connected";
  $("practice-controls").hidden = tab !== "practice";
  $("connected-controls").hidden = tab !== "connected";
  $("free-controls").hidden = tab !== "free";
  $("listen-step").hidden = $("step-num-2").hidden = tab !== "practice" && tab !== "connected";
  const mode = { practice: "target", connected: "connected", free: "free" }[tab];
  $("results").hidden = tab === "lookup" || !state.result || state.result.mode !== mode;
  if (tab === "connected" && !state.topics) loadTopics();
}

/* ---------- Model status ---------- */
async function pollStatus() {
  try {
    const s = await (await fetch("/api/status")).json();
    const el = $("model-status");
    if (s.phoneme_model && s.whisper_model) {
      el.hidden = true;
      return;
    }
    el.textContent = "Loading models…";
  } catch { /* server restarting */ }
  setTimeout(pollStatus, 2000);
}
pollStatus();

/* ---------- Practice sentences ---------- */
// A random sentence from the practice list; "Get new sentence" draws another, without repeating
// any until the whole list has been seen.
let practiceQueue = [];
let practiceAll = [];
function nextSentence() {
  if (!practiceQueue.length) {
    practiceQueue = practiceAll.slice();
    for (let i = practiceQueue.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [practiceQueue[i], practiceQueue[j]] = [practiceQueue[j], practiceQueue[i]];
    }
  }
  setTarget(practiceQueue.pop());
}
async function loadSentences() {
  practiceAll = await (await fetch("/api/sentences")).json();
  const b = document.createElement("button");
  b.className = "chip";
  b.textContent = "Get new sentence";
  b.addEventListener("click", nextSentence);
  $("focus-chips").appendChild(b);
  nextSentence();
}

let ipaTimer = null;
function setTarget(text) {
  $("target").value = text;
  $("target-ipa").textContent = "";  // don't show the previous sentence's pronunciation
  updateTargetIpa();
}
function updateTargetIpa() {
  clearTimeout(ipaTimer);
  ipaTimer = setTimeout(async () => {
    const text = $("target").value.trim();
    if (!text) { $("target-ipa").textContent = ""; return; }
    try {
      const r = await fetch("/api/pronounce?text=" + encodeURIComponent(text));
      if (!r.ok) return;
      const d = await r.json();
      if ($("target").value.trim() !== text) return;  // the sentence changed while this was loading
      $("target-ipa").innerHTML = `<strong>${esc(d.respelling)}</strong><span class="ipa target-ipa-line">/${esc(d.ipa)}/</span>`;
    } catch { /* ignore */ }
  }, 250);
}
$("target").addEventListener("input", updateTargetIpa);
$("btn-listen-target").addEventListener("click", (e) => {
  if (state.tab === "connected") {
    if (state.cs) speakUrl(`/api/connected/speak?topic=${state.cs.topic}&sentence=${state.cs.index}`, e.currentTarget);
  } else speak($("target").value, e.currentTarget);
});

/* ---------- Recording ---------- */
$("btn-record").addEventListener("click", () => (state.recording ? stopRecording() : startRecording()));

async function startRecording() {
  hideError();
  if (state.tab === "practice" && !$("target").value.trim()) {
    return showError("Type or choose a sentence to practice first.");
  }
  if (state.tab === "connected" && !state.cs) return showError("Choose a sentence to practice first.");
  let stream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true },
    });
  } catch (e) {
    return showError("Microphone access was blocked. Allow microphone access for this page and try again.");
  }
  const mime = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4", "audio/ogg"].find((m) => MediaRecorder.isTypeSupported(m));
  state.recorder = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined);
  state.chunks = [];
  state.recorder.ondataavailable = (e) => e.data.size && state.chunks.push(e.data);
  state.recorder.onstop = () => {
    stream.getTracks().forEach((t) => t.stop());
    const blob = new Blob(state.chunks, { type: state.recorder.mimeType || "audio/webm" });
    submitRecording(blob);
  };
  state.recorder.start();
  state.recording = true;
  state.startedAt = Date.now();
  $("btn-record").classList.add("recording");
  $("rec-state").textContent = "Stop";
  state.timer = setInterval(() => {
    const s = Math.floor((Date.now() - state.startedAt) / 1000);
    $("rec-timer").textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
    if (s >= 60) stopRecording();
  }, 250);
}

function stopRecording() {
  if (!state.recording) return;
  state.recording = false;
  clearInterval(state.timer);
  $("btn-record").classList.remove("recording");
  state.recorder.stop();
}

async function submitRecording(blob) {
  if (state.audioUrl) URL.revokeObjectURL(state.audioUrl);
  state.audioUrl = URL.createObjectURL(blob);
  const pb = $("playback");
  pb.src = state.audioUrl;
  pb.hidden = false;

  const btn = $("btn-record");
  btn.classList.add("busy");
  btn.disabled = true;
  $("rec-state").textContent = "Analyzing…";

  const form = new FormData();
  form.append("audio", blob, "recording");
  form.append("target", state.tab === "practice" ? $("target").value : "");
  if (state.tab === "connected" && state.cs) {
    form.append("topic", state.cs.topic);
    form.append("sentence", state.cs.index);
  }
  try {
    const r = await fetch("/api/analyze", { method: "POST", body: form });
    const d = await r.json();
    if (!r.ok) throw new Error(d.detail || "Analysis failed.");
    state.result = d;
    state.analyzed = await decodeAnalyzedAudio(d.audio_wav);
    renderResults(d);
  } catch (e) {
    showError(e.message);
  } finally {
    btn.classList.remove("busy");
    btn.disabled = false;
    $("rec-state").textContent = "Record again";
  }
}

function showError(msg) { $("error").textContent = msg; $("error").hidden = false; }
function hideError() { $("error").hidden = true; }

/* ---------- Results ---------- */
const confirmed = (w) => (w.issues || []).filter((x) => x.confidence !== "possible");

// Lead with what went right: "23 of 26 sounds American · 3 to fix".
function verdictFor(d) {
  const known = d.words.filter((w) => w.known && w.phones);
  const total = known.reduce((n, w) => n + w.phones.filter((p) => p.expected).length, 0);
  const toFix = known.reduce((n, w) => n + confirmed(w).length, 0);
  const wrong = known.reduce((n, w) => n + confirmed(w).filter((x) => x.type !== "extra").length, 0);
  if (!total) return "No words I could score.";
  if (toFix === 0) return total === 1 ? "That sound is American." : `All ${total} sounds American. Excellent.`;
  return `${total - wrong} of ${total} sounds American · ${toFix} to fix`;
}

function renderResults(d) {
  $("results").hidden = false;
  const ring = $("score-ring");
  ring.style.setProperty("--p", d.overall);
  ring.style.setProperty("--c", d.overall >= 85 ? "var(--good)" : d.overall >= 60 ? "var(--fair)" : "var(--poor)");
  $("score").textContent = d.overall;
  $("verdict").textContent = verdictFor(d);
  $("btn-retry").hidden = d.mode === "free";
  renderConnectedResult(d);
  $("transcript").textContent = d.transcript ? `“${d.transcript}”` : "—";
  $("expected-respelling").textContent = d.expected_respelling;
  $("heard-respelling").textContent = d.heard_respelling;
  $("expected-ipa").textContent = "/" + d.expected_ipa + "/";
  $("heard-ipa").textContent = "/" + d.heard_ipa + "/";

  const chips = $("word-chips");
  chips.innerHTML = "";
  d.words.forEach((w, i) => {
    const b = document.createElement("button");
    b.className = `w ${w.status}`;
    b.innerHTML = `<span class="wt">${esc(w.word)}</span><small>${w.known ? esc(w.respelling) : "—"}</small>`;
    b.title = w.score == null ? "Not in the dictionary" : `${w.score}%`;
    b.addEventListener("click", () => selectWord(i));
    chips.appendChild(b);
  });

  // Patterns arrive ranked by how much they matter: the first confirmed one is the focus.
  const pats = d.patterns || [];
  const focus = pats.length && pats[0].confirmed ? pats[0] : null;
  const rest = focus ? pats.slice(1) : pats;
  state.focus = focus;
  renderFocus(focus);
  $("patterns-box").hidden = rest.length === 0;
  $("patterns").innerHTML = rest
    .map((p) => `<li><span class="pl">${esc(p.label)}<span class="ipa pc"><br>${esc(p.label_ipa)}</span><br><span class="impact ${p.impact}">${IMPACT_LABEL[p.impact]}</span></span><span>${esc(p.tip)}${p.count > 1 ? ` <span class="pc">×${p.count}</span>` : ""}</span></li>`)
    .join("");

  // Open the word that shows the focus mistake; without one, the lowest-scoring word.
  const worst = d.words.reduce((best, w, i) => (w.score != null && (best < 0 || w.score < d.words[best].score) ? i : best), -1);
  if (focus) selectWord(focus.words[0].index);
  else if (worst >= 0 && d.words[worst].score < 85) selectWord(worst);
  else $("word-detail").hidden = true;
}

const IMPACT_LABEL = { high: "Changes words", medium: "Very noticeable", low: "Finishing touch" };

function renderFocus(p) {
  const box = $("focus");
  box.hidden = !p;
  if (!p) return;
  const words = p.words
    .map((w) => `<button class="mini" data-word="${w.index}">${esc(w.word)}</button>`)
    .join(" ");
  box.innerHTML = `
    <div class="label">Fix this first</div>
    <div class="focus-words">${words}</div>
    <p class="focus-title">${esc(p.label)} <span class="ipa pc">${esc(p.label_ipa)}</span></p>
    <p class="focus-why">${esc(p.why)}</p>
    <p class="focus-tip">${esc(p.tip)}</p>`;
  box.querySelectorAll("[data-word]").forEach((b) =>
    b.addEventListener("click", () => {
      selectWord(+b.dataset.word);
      $("word-detail").scrollIntoView({ behavior: "smooth", block: "start" });
    }));
}

/* Word clips play from the exact audio the server analyzed (same timeline as the word
   timings), through Web Audio, so there is no seeking in the browser's recording. */
let audioCtx = null;
async function decodeAnalyzedAudio(b64) {
  if (!b64) return null;
  audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return audioCtx.decodeAudioData(bytes.buffer);
}

let currentClip = null;
function playSegment(start, end) {
  const buf = state.analyzed;
  if (!buf) return;
  if (audioCtx.state === "suspended") audioCtx.resume();
  stopAudio();
  const s = Math.max(0, start);
  const dur = Math.max(0.05, Math.min(buf.duration, end) - s);
  const src = audioCtx.createBufferSource();
  const gain = audioCtx.createGain();
  const t = audioCtx.currentTime;
  // 10 ms fades so clips don't click at the cut points.
  gain.gain.setValueAtTime(0, t);
  gain.gain.linearRampToValueAtTime(1, t + 0.01);
  gain.gain.setValueAtTime(1, t + Math.max(0.01, dur - 0.01));
  gain.gain.linearRampToValueAtTime(0, t + dur);
  src.buffer = buf;
  src.connect(gain).connect(audioCtx.destination);
  src.start(t, s, dur);
  currentClip = src;
}

function selectWord(i) {
  state.selected = i;
  const w = state.result.words[i];
  document.querySelectorAll("#word-chips .w").forEach((el, k) => el.classList.toggle("selected", k === i));
  const box = $("word-detail");
  box.hidden = false;

  if (!w.known) {
    box.innerHTML = `<div class="wd-head"><span class="wd-word">${esc(w.word)}</span>
      <span class="wd-buttons"><button class="mini" data-say="${esc(w.word)}">American version</button></span></div>
      <p class="hint">Not in the dictionary.</p>`;
    bindSay(box);
    return;
  }

  const phones = (w.phones || [])
    .map((p) => {
      const yours = p.status === "ok" ? "✓" : p.status === "missing" ? "missing" : `you: ${p.heard_say}`;
      const ipa = `<span class="h ipa">/${esc(p.expected || "+")}/ → /${esc(p.heard || "—")}/</span>`;
      return `<div class="ph ${p.status}">${soundTile(p.expected_say, p.expected_example)}<span class="h">${esc(yours)}</span>${ipa}</div>`;
    })
    .join("");
  // The mistake already explained in "Fix this first" is only pointed to, not repeated.
  const focus = state.focus;
  const shown = focus && focus.words.some((fw) => fw.index === i) ? focus.tip : null;
  const issues = w.issues.length
    ? `<ol class="issues">${w.issues.map((x) => x.tip === shown
        ? `<li class="${x.severity}">${esc(focus.label)}: see “Fix this first” above.</li>`
        : x.confidence === "possible"
        ? `<li class="possible"><span class="maybe">Possibly</span>${esc(x.tip)}</li>`
        : `<li class="${x.severity}">${esc(x.tip)}</li>`).join("")}</ol>`
    : `<p class="ok-msg">Correct.</p>`;
  const understood = w.understood === false ? `<p class="hint">Not understood by the listener.</p>` : "";

  box.innerHTML = `
    <div class="wd-head">
      <span class="wd-word">${esc(w.word)}<span class="badge ${w.status}">${w.score} of 100</span></span>
      <span class="wd-buttons">
        <button class="mini" data-say="${esc(w.word)}">American version</button>
        ${w.start != null ? `<button class="mini" id="btn-mine">Your version</button>` : ""}
      </span>
    </div>
    <dl class="pron-grid">
      <dt>Say it like</dt><dd class="respell-big">${esc(w.respelling)}</dd>
      <dt>You said</dt><dd>${esc(w.heard_respelling)}</dd>
      <dt>IPA (correct)</dt><dd class="big ipa">${esc(w.ipa)}</dd>
      <dt>IPA (yours)</dt><dd class="ipa">${esc(w.heard_ipa)}</dd>
      ${w.variants && w.variants.length ? `<dt>Also accepted</dt><dd class="ipa">${w.variants.map(esc).join(", ")}</dd>` : ""}
    </dl>
    <div class="label">Sound by sound</div>
    <div class="phones">${phones}</div>
    ${understood}
    ${issues}
  `;
  bindSay(box);
  const mine = $("btn-mine");
  if (mine) mine.addEventListener("click", () => playSegment(w.start, w.end));
}

function bindSay(root) {
  root.querySelectorAll("[data-say]").forEach((b) =>
    b.addEventListener("click", () => speak(b.dataset.say, b))
  );
}

$("btn-retry").addEventListener("click", () => {
  $("record-panel").scrollIntoView({ behavior: "smooth", block: "start" });
  if (!state.recording) startRecording();
});

/* ---------- Connected speech ---------- */
const LEVELS = {
  1: ["Everyone does this", "even in careful speech"],
  2: ["Everyday speech", "how most Americans talk"],
  3: ["Casual speech", "with friends and family"],
};

async function loadTopics() {
  const box = $("connected-panel");
  box.innerHTML = `<p class="hint">Loading…</p>`;
  try {
    state.topics = await (await fetch("/api/connected")).json();
  } catch {
    box.innerHTML = `<div class="error-box">Couldn't load the lessons. Try again in a moment.</div>`;
    return;
  }
  renderTopicList();
}

function renderTopicList() {
  const box = $("connected-panel");
  const byLevel = [1, 2, 3].map((lvl) => {
    const topics = state.topics.filter((t) => t.level === lvl);
    if (!topics.length) return "";
    return `<h3 class="cs-level">${LEVELS[lvl][0]}<small>${LEVELS[lvl][1]}</small></h3>
      <div class="cs-topics">${topics.map((t) =>
        `<button class="cs-topic" data-topic="${esc(t.id)}"><b>${esc(t.title)}</b><span>${esc(t.rule)}</span></button>`).join("")}</div>`;
  }).join("");
  box.innerHTML = `<p class="cs-intro">Americans don't say words one at a time. Learn how they join, shrink and drop sounds, then say it the same way.</p>${byLevel}`;
  box.querySelectorAll("[data-topic]").forEach((b) => b.addEventListener("click", () => openTopic(b.dataset.topic)));
}

function openTopic(id) {
  const t = state.topics.find((x) => x.id === id);
  const box = $("connected-panel");
  const items = t.items.map((it, k) => `
    <div class="cs-item" role="button" tabindex="0" data-practice="${k}" title="Practice sentences with “${esc(it.written)}”">
      <span class="from">${esc(it.written)} →</span>
      <span class="to">${esc(it.spoken)}</span>
      <span class="ipa">/${esc(it.ipa)}/</span>
      ${it.note ? `<p class="note">${esc(it.note)}</p>` : ""}
      <button class="mini" data-item="${k}">American version</button>
      <span class="go">Practice ↓</span>
    </div>`).join("");
  const sentences = t.sentences.map((s, k) =>
    `<li><button data-sentence="${k}">${esc(s.text)}<small>${esc(s.spoken)}</small></button></li>`).join("");
  box.innerHTML = `
    <button class="mini cs-back">← All topics</button>
    <h2 class="cs-title">${esc(t.title)}</h2>
    <span class="pc">${LEVELS[t.level][0]}</span>
    <p class="cs-rule">${esc(t.rule)}</p>
    <p class="cs-how">${esc(t.how)}</p>
    ${items ? `<h3 class="minor-title">Say it like this</h3><div class="cs-items">${items}</div>` : ""}
    <h3 class="minor-title">Practice sentences</h3>
    <ul class="cs-sentences">${sentences}</ul>`;
  box.querySelector(".cs-back").addEventListener("click", () => {
    state.cs = null;
    $("results").hidden = true;
    setTab("connected");
    renderTopicList();
    box.scrollIntoView({ behavior: "smooth", block: "start" });
  });
  box.querySelectorAll("[data-item]").forEach((b) => b.addEventListener("click", (e) => {
    e.stopPropagation();  // play only; don't also jump to the sentences
    speakUrl(`/api/connected/speak?topic=${t.id}&item=${b.dataset.item}`, b);
  }));
  box.querySelectorAll("[data-practice]").forEach((card) => {
    const go = () => practiceItem(t, +card.dataset.practice);
    card.addEventListener("click", go);
    card.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); go(); } });
  });
  box.querySelectorAll("[data-sentence]").forEach((b) => b.addEventListener("click", () => chooseSentence(t, +b.dataset.sentence)));
  state.cs = null;
  $("results").hidden = true;
  setTab("connected");
  box.scrollIntoView({ behavior: "smooth", block: "start" });
}

// Jump to the practice sentences that use one item, mark them, and get the first one ready to record.
function practiceItem(t, k) {
  const name = t.items[k].written;
  const matches = t.sentences.map((s, i) => (s.items.includes(name) ? i : -1)).filter((i) => i >= 0);
  document.querySelectorAll("#connected-panel [data-sentence]").forEach((b) =>
    b.classList.toggle("match", matches.includes(+b.dataset.sentence)));
  if (!matches.length) return;
  chooseSentence(t, matches[0], false);
  document.querySelector(`#connected-panel [data-sentence="${matches[0]}"]`)
    .scrollIntoView({ behavior: "smooth", block: "center" });
}

function chooseSentence(t, index, scroll = true) {
  const s = t.sentences[index];
  state.cs = { topic: t.id, index, sentence: s };
  document.querySelectorAll("#connected-panel [data-sentence]").forEach((b) =>
    b.classList.toggle("active", +b.dataset.sentence === index));
  $("cs-sentence").textContent = s.text;
  $("cs-spoken").textContent = s.spoken;
  $("results").hidden = true;
  hideError();
  setTab("connected");
  if (scroll) $("record-panel").scrollIntoView({ behavior: "smooth", block: "start" });
}

// Which form the speaker used for each item: casual (the American way) or careful (still correct).
function renderConnectedResult(d) {
  const box = $("cs-result");
  const items = d.mode === "connected" ? d.words.filter((w) => w.item) : [];
  box.hidden = !items.length;
  if (!items.length) return;
  box.innerHTML = `<div class="label">Connected speech</div>` + items.map((w) => w.item.used === "casual"
    ? `<p>✓ <strong>${esc(w.item.written)}</strong> → ${esc(w.item.spoken)}. You said it the American way.</p>`
    : `<p class="careful"><strong>${esc(w.item.written)}</strong>: you said it in full. That's correct, but Americans say <strong>${esc(w.item.spoken)}</strong> here.</p>`).join("");
}

/* ---------- Lookup ---------- */
$("lookup-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const text = $("lookup-input").value.trim();
  const out = $("lookup-results");
  if (!text) return;
  const r = await fetch("/api/pronounce?text=" + encodeURIComponent(text));
  const d = await r.json();
  if (!r.ok) { out.innerHTML = `<div class="error-box">${esc(d.detail)}</div>`; return; }
  const sentence = d.words.length > 1
    ? `<div class="lookup-sentence"><div class="respell-big">${esc(d.respelling)}</div><div class="ipa">/${esc(d.ipa)}/</div>
       <button class="mini" data-say="${esc(text)}">American version</button></div>`
    : "";
  out.innerHTML = sentence + d.words.map((w) => w.known ? `
    <div class="lookup-card">
      <div class="wd-head"><span class="wd-word">${esc(w.word)}</span>
        <span class="wd-buttons"><button class="mini" data-say="${esc(w.word)}">American version</button></span></div>
      <dl class="pron-grid">
        <dt>Say it like</dt><dd><span class="respell-big">${esc(w.respelling)}</span></dd>
        <dt>American IPA</dt><dd class="big ipa">${esc(w.ipa)}</dd>
        ${w.variants.length ? `<dt>Also accepted</dt><dd class="ipa">${w.variants.map(esc).join(", ")}</dd>` : ""}
      </dl>
      ${w.notes.length ? `<ul class="notes">${w.notes.map((n) => `<li>${esc(n)}</li>`).join("")}</ul>` : ""}
    </div>` : `<div class="lookup-card"><span class="wd-word">${esc(w.word)}</span> <span class="hint">not in the dictionary</span></div>`).join("");
  bindSay(out);
});

/* ---------- Keyboard: space toggles recording ---------- */
document.addEventListener("keydown", (e) => {
  if (e.code === "Space" && !["TEXTAREA", "INPUT", "BUTTON"].includes(document.activeElement.tagName) && state.tab !== "lookup") {
    e.preventDefault();
    state.recording ? stopRecording() : startRecording();
  }
});

loadSentences();
setTab("practice");
